<script setup lang="ts">import{computed}from'vue';import{useRoute,useRouter}from'vue-router';import{session}from'@/api';const route=useRoute(),router=useRouter();const title=computed(()=>route.meta.title??'Przegląd');const isPublic=computed(()=>Boolean(route.meta.public));const user=computed(()=>session.user);const links=[['/','Przegląd','⌂'],['/transakcje','Transakcje','↕'],['/transfery','Przelewy','⇄'],['/konta','Konta','▣'],['/kategorie','Kategorie','◌'],['/raporty','Raporty','◔'],['/import','Import','⇧']];function logout(){session.clear();router.push('/auth')}</script>
<template><RouterView v-if="isPublic"/><div v-else class="app-shell"><aside class="sidebar"><div class="grosik-logo"><span>G</span><b>rosik</b></div><p class="nav-label">FINANSE</p><nav><RouterLink v-for="l in links" :key="l[0]" :to="l[0]"><i>{{l[2]}}</i>{{l[1]}}</RouterLink></nav><button class="logout" @click="logout">Wyloguj</button><div class="sidebar-footer"><span class="avatar">{{user?.email?.slice(0,2).toUpperCase()||'G'}}</span><div><strong>{{user?.email||'Gospodarstwo'}}</strong><small>Grosik</small></div></div></aside><main><header><div><p class="eyebrow">GROSIK · FINANSE DOMOWE</p><h1>{{title}}</h1></div><div class="header-actions"><button class="icon-button">⌕</button><button class="icon-button">♧</button><RouterLink class="button primary" to="/transakcje">+ Dodaj wydatek</RouterLink></div></header><RouterView/></main></div></template>
